import localExporter from './google-local-auth.js';

export function googleAuthorizationPage() {
  return `<!doctype html><html lang="zh-Hans"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>重新授权 Google 会话</title><script src="/google-authorization/client.js" defer></script><style>body{font:16px/1.7 system-ui;background:#f4f5ef;color:#193b30}main{max-width:760px;margin:40px auto;padding:24px;background:white;border-radius:12px}button,a{color:#245e49}button{padding:10px 18px;margin:16px 0}code,pre{background:#eef2e8;padding:4px 8px}pre{white-space:pre-wrap}#message{white-space:pre-wrap}</style></head><body><main><h1>重新授权 Google 会话</h1><p>此入口使用本站私有 OAuth。密码和验证码只输入你电脑上的 Google 官方页面。</p><ol><li>电脑上安装 Python 3 和 Google Chrome，<a href="/google-authorization/export.py">下载授权脚本</a>。</li><li>在脚本所在目录打开终端，执行：<pre>python -m pip install playwright
python google-local-auth.py</pre>输入与你 BundleFoundry 相同的邮箱，在打开的 Chrome 中完成登录。</li><li>脚本自动核对账号并关闭 Chrome，生成 <code>google-session-import.json</code>。在下方上传该文件。</li></ol><p>这个文件包含敏感会话资料；只上传到本页，完成后从电脑删除。Render 将使用独立密钥加密保存，本站数据库保存密文。</p><form id="import"><input id="file" type="file" accept="application/json,.json" required><br><button type="submit">保存授权并执行云端失效测试</button></form><p id="message" role="status" aria-live="polite"></p><p><a href="/">返回领取中心</a></p></main></body></html>`;
}

export const googleAuthorizationScript = `
const form=document.getElementById('import'),message=document.getElementById('message');
async function post(path,body){const response=await fetch(path,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const result=await response.json();if(!response.ok)throw Error(({forbidden:'请使用本站所有者身份登录。',run_in_progress:'已有任务运行中，请稍后重试。',invalid_batch:'文件格式或账号不正确。',upstream_run_incomplete:'云端未完成，请保留文件并稍后重试。',session_test_disabled:'失效测试尚未启用，请联系维护者。'})[result.error]||'操作未完成，请稍后重试。');return result;}
form.addEventListener('submit',async event=>{event.preventDefault();const button=form.querySelector('button');button.disabled=true;let imported=false;try{const file=document.getElementById('file').files[0];if(!file||file.size>250000)throw Error('请选择脚本生成的文件（最大 250 KB）。');let data=JSON.parse(await file.text());const account=data.account;if(data.version!==1||typeof account!=='string')throw Error('授权文件格式不正确。');message.textContent='正在核对账号并加密保存…';await post('/api/google/import',{source_account:account,messages:[],google_session_import:data});imported=true;data=null;document.getElementById('file').value='';message.textContent='授权已保存，正在云端清除 BundleFoundry Cookie 并测试自动登录…';const result=await post('/api/session-recovery/test',{source_account:account,messages:[]});if(result.session_recovery_test?.site_session_valid_after_login!==true)throw Error('云端测试尚未通过。');message.textContent='云端失效测试通过：系统已复用 Google 会话自动重新登录，账号及新会话核验通过。请删除电脑上的授权文件。';}catch(error){message.textContent=(imported?'授权已保存；失效测试未通过。':'')+error.message;}finally{button.disabled=false;}});
`;

export {localExporter};
